/* Graphide Verdigris Ink: gred's shape, density, type and flatness.
   Read from graphide-ide/gred-rs/crates/ui/src/theme.rs (Theme::ink,
   Theme::marble, Docks::of_roles), typography.rs, control.rs and the
   rendered frames in docs/Tech/gred/native/frames/. The colours are in the
   theme's roles; this holds the form, which is what carries the look. */
:root{
/* -- Shape: gred button 5, chip 4, well 6, card 12 -- */
--radius:0.375rem;--radius-xs:0.125rem;--control-radius:5px;
/* -- Density: Tailwind's base unit, 12% tighter -- */
--spacing:0.22rem;
/* -- Type: gred's 8 steps (caption 11, small 12, body 13, title 15, display 20) -- */
--text-2xs:0.625rem;--text-xs:0.6875rem;--text-sm:0.8125rem;--text-base:0.9375rem;--text-lg:1.0625rem;--text-xl:1.25rem;
--text-xs--line-height:1.35;--text-sm--line-height:1.45;--text-base--line-height:1.45;--text-lg--line-height:1.3;--text-xl--line-height:1.2;
--leading-normal:1.45;--leading-snug:1.35;--leading-tight:1.25;
--tracking-tight:-0.01em;--tracking-tighter:-0.02em;--tracking-widest:0.08em;
--font-sans:"Inter Variable","Inter",ui-sans-serif,system-ui,sans-serif;
--font-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
--font-size-prompt:0.8125rem;--font-size-code:0.78125rem;
/* -- Layout: gred's measures. Bar 28 (36 here for web hit targets),
      reading width 860, sidebar 280, right dock 336. -- */
--workspace-topbar-height:36px;
--workspace-titlebar-control-size:1.5rem;--workspace-titlebar-control-gap:0.5rem;
--workspace-titlebar-scroll-fade-height:0px;
--workspace-gutter:0.75rem;
--chat-content-max-width:53.75rem;
--thread-details-panel-width:21rem;
--sidebar-width:17rem;
--sidebar-content-inset:0.375rem;--sidebar-row-content-inset:0.5rem;--sidebar-control-gap:0.375rem;
--command-shell-inset:0.375rem;--command-content-inset:0.75rem;--floating-content-inset:0.5rem;
/* -- gred paints flat: no glass, no grain, no decorative fade -- */
--glass-blur:0px;--glass-opacity:100%;--glass-saturation:1;
--surface-grain:none;
--app-scrollbar-width:6px;
/* -- the roles this sheet names, as gred's theme names them -- */
--gr-line:#ffffff14;--gr-bright:#dae1e6;--gr-faint:#52616b;--gr-sunken:#0d161c;
--gr-sel:#18242c;--gr-raised:#1f2c35;--gr-accent:#4fa396;--gr-thumb:#232b31;--gr-thumb-on:#353d43}
:root:not(.dark){--gr-line:#0000002b;--gr-bright:#0f1420;--gr-faint:#8a949c;--gr-sunken:#e7edea;
--gr-sel:#d5e3df;--gr-raised:#ffffff;--gr-accent:#2a7a6e;--gr-thumb:#d6dfdb;--gr-thumb-on:#c3cfca}

/* Depth comes from surface, never shadow. Focus rings stay. */
[data-slot="sidebar-inner"],[data-slot="composer-host"],[data-user-message-bubble],[data-thread-details-card],[data-timeline-row-kind],.chat-markdown-codeblock,[data-slot="dialog-popup"],[data-slot="dialog-panel"],[data-slot="sheet-popup"],[data-slot="sheet-panel"],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="select-popup"],[data-slot="tooltip-popup"],[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"],[data-slot="badge"],[data-thread-item],[data-chat-header]{box-shadow:none !important;backdrop-filter:none !important}
[data-slot="button"]:focus-visible,[data-slot="input"]:focus-visible,[data-slot="select-trigger"]:focus-visible{outline:2px solid var(--gr-accent);outline-offset:-1px}

/* Controls at gred's metrics. */
[data-slot="button"]{min-height:28px;border-radius:5px !important;font-size:12px;font-weight:500}
[data-slot="input"],[data-slot="input-control"],[data-slot="textarea-control"],[data-slot="select-trigger"]{min-height:28px;border-radius:6px !important;border-color:var(--gr-line) !important;font-size:13px}
[data-slot="menu-item"],[data-slot="command-item"],[data-slot="menu-checkbox-item"]{min-height:30px;border-radius:4px !important}

/* The thread list is gred's agents list: rows on the page itself, the one
   you are in carried by the selection and an accent bar at its left edge,
   not by a pill. (Docks::of_roles: sidebar = page, sidebar_active =
   selection; the frames show the bar.) */
[data-thread-item],[data-sidebar-row]{border-radius:3px !important}
[data-sidebar-row]{position:relative}
[data-sidebar-row][aria-current="page"]::before{content:"";position:absolute;left:0;top:2px;bottom:2px;width:2px;border-radius:1px;background:var(--gr-accent)}
[data-sidebar-row]:focus-visible{outline:1px solid var(--gr-accent);outline-offset:-1px}

/* Hairlines, never a grey border. */
[data-slot="separator"]{background:var(--gr-line) !important}

/* gred's tag and key chip. */
[data-slot="badge"]{border-radius:4px !important;font-size:11px;font-weight:600;letter-spacing:0.01em}
[data-slot="kbd"],kbd,[data-slot="context-chip"],.chat-markdown :not(pre)>code{font-family:var(--font-mono);font-size:11px;line-height:1.35;background:var(--gr-sunken);border:1px solid var(--gr-line);border-radius:4px;padding:1px 5px}
[data-slot="kbd"],kbd{color:var(--gr-faint)}

/* The eyebrow: mono 9.5, weight 600, +0.08 tracking, upper. */
[data-slot="sidebar-group-label"],[data-sidebar="group-label"],[data-sidebar="group"]>[data-slot="label"],[data-slot="settings-group"]>[data-slot="label"]{font-family:var(--font-mono) !important;font-size:9.5px !important;font-weight:600 !important;letter-spacing:0.08em !important;text-transform:uppercase !important;color:var(--gr-faint) !important}

/* Headings take the bright step. */
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3,.chat-markdown h4{color:var(--gr-bright);font-weight:600;letter-spacing:-0.01em;line-height:1.25}

/* Conversation. */
[data-user-message-bubble]{border-radius:6px !important;border:1px solid var(--gr-line) !important}

/* Composer: the field lies on the page itself (Theme::ink: field = page),
   a hairline around it and the accent only while it has the keys. */
[data-slot="composer-host"]{--chat-composer-outline:var(--gr-line);--chat-composer-glass-surface:transparent;--chat-composer-attached-surface:transparent;--chat-composer-highlight:transparent;--chat-composer-attached-seam:var(--gr-line);border-radius:6px !important}
[data-slot="composer-host"]:focus-within{--chat-composer-outline:var(--gr-accent)}
.composer-tiptap{font-family:var(--font-mono);font-size:13px}

/* Code: gred mono 12.5, sunken, hairline. */
.chat-markdown-codeblock{border-radius:6px !important;border:1px solid var(--gr-line) !important;font-size:12.5px}
[data-thread-details-card]{border-radius:6px !important;border:1px solid var(--gr-line) !important}

/* Sheets: raised, hairline, radius 8. */
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="select-popup"],[data-slot="sheet-popup"]{border:1px solid var(--gr-line) !important;border-radius:8px !important}
[data-slot="tooltip-popup"]{border-radius:4px !important;font-size:11px}
[data-chat-header]{border-bottom:1px solid var(--gr-line) !important}

/* Icons: gred's round-cap strokes. */
svg.lucide{stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}

::-webkit-scrollbar{width:6px;height:6px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--gr-thumb);border-radius:2px}
::-webkit-scrollbar-thumb:hover{background:var(--gr-thumb-on)}
[data-slot="scroll-area-thumb"]{background:var(--gr-thumb) !important;border-radius:2px !important}
